function play(src){stopAudio();curAudio=new Audio(A+src);curAudio.play().catch(()=>{});}function stopAudio(){if(curAudio){curAudio.pause();curAudio.currentTime=0;curAudio=null;}}function sfx(src){new Audio(A+src).play().catch(()=>{});}function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1400);}function shuffle(a){return[...a].sort(()=>Math.random()-.5)}
function addScreen(title,html,init,{assessment=false}={}){const el=document.createElement('section');el.className='screen'+(assessment?' assessment':'');el.innerHTML=html;host.appendChild(el);const api=init?init(el):{};screens.push({title,el,...api});}
function show(i){i=Math.max(0,Math.min(screens.length-1,i));screens[cur]?.onLeave?.();stopAudio();clearInterval(liveTimer);cur=i;screens.forEach((s,n)=>s.el.classList.toggle('active',n===i));$('#objective').textContent=screens[i].title;$('#page-num').textContent=`${i+1} / ${screens.length}`;$('#progress').style.width=`${(i+1)/screens.length*100}%`;$('#btn-prev').disabled=i===0;$('#btn-next').disabled=i===screens.length-1;document.querySelectorAll('#thumbs button').forEach((b,n)=>b.classList.toggle('cur',n===i));screens[i].onEnter?.()}
function fit(){const z=Math.min(innerWidth/1280,innerHeight/720);$('#stage').style.transform=`scale(${z})`}addEventListener('resize',fit);
$('#btn-ar').onclick=()=>{const on=document.body.classList.toggle('ar-on');$('#btn-ar').setAttribute('aria-pressed',String(on))};$('#btn-teacher').onclick=()=>{const on=document.body.classList.toggle('teacher-on');$('#btn-teacher').setAttribute('aria-pressed',String(on))};$('#btn-prev').onclick=()=>show(cur-1);$('#btn-next').onclick=()=>show(cur+1);$('#btn-pages').onclick=()=>$('#thumbs').classList.toggle('open');$('#btn-fs').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{});document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(cur+1);if(e.key==='ArrowLeft')show(cur-1)});host.addEventListener('click',e=>{const b=e.target.closest('[data-audio]');if(b)play(b.dataset.audio)});

