function noAr(){document.body.classList.remove('ar-on');$('#btn-ar').setAttribute('aria-pressed','false')}
function ltrBtn(L){return `<button class="word-opt" data-w="${L}" style="color:${TILE[L]}">${L}</button>`}
function swBtn(c){return `<button class="swatch-chip" data-w="${c.en}" style="background:${c.hex}"></button>`}
function balloonCol(c,x,y){return `<svg class="balloon" data-w="${c.en}" style="left:${x}px;top:${y}px" viewBox="0 0 96 120"><ellipse cx="48" cy="46" rx="40" ry="44" fill="${c.hex}"/><polygon points="48,92 40,106 56,106" fill="${c.hex}"/></svg>`}
function balloonLtr(L,x,y){return `<svg class="balloon" data-w="${L}" style="left:${x}px;top:${y}px" viewBox="0 0 96 120"><ellipse cx="48" cy="46" rx="40" ry="44" fill="#ffffff" stroke="${TILE[L]}" stroke-width="5"/><text x="48" y="60" text-anchor="middle" font-size="40" font-weight="900" fill="${TILE[L]}">${L}</text><polygon points="48,92 40,106 56,106" fill="#ffffff" stroke="${TILE[L]}" stroke-width="4"/></svg>`}
const ARROW='<svg width="60" height="34" viewBox="0 0 74 40"><path d="M4 20 H56 M44 6 L60 20 L44 34" stroke="#ff735e" stroke-width="9" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
function icSVG(k){const m={wave:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#ff735e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 12V5.5a1.5 1.5 0 0 1 3 0V11m0-6.5v-1a1.5 1.5 0 0 1 3 0V11m0-5.5a1.5 1.5 0 0 1 3 0V12m0-4a1.5 1.5 0 0 1 3 0v5a7 7 0 0 1-7 7h-1a7 7 0 0 1-6-3.3L4.6 17a1.6 1.6 0 0 1 .4-2.6 1.6 1.6 0 0 1 2 .4z"/></svg>',chat:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#1670e8" stroke-width="2"><path d="M21 12a8 8 0 0 1-8 8H4l2-3a8 8 0 1 1 15-5z"/><path d="M8.5 12h.01M12 12h.01M15.5 12h.01" stroke-linecap="round" stroke-width="3"/></svg>',heart:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#ff6fb5" stroke-width="2" stroke-linejoin="round"><path d="M12 20s-7-4.6-9.3-9A5.2 5.2 0 0 1 12 6.5 5.2 5.2 0 0 1 21.3 11C19 15.4 12 20 12 20z"/></svg>',palette:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#37b56a" stroke-width="2"><path d="M12 3a9 9 0 1 0 0 18c1.5 0 2-1 1.4-2.2-.7-1.3.1-2.3 1.6-2.3H17a4 4 0 0 0 4-4c0-5.2-4-9.5-9-9.5z"/><circle cx="7.5" cy="11.5" r="1.3" fill="#2f80ed" stroke="none"/><circle cx="12" cy="7.5" r="1.3" fill="#37b56a" stroke="none"/><circle cx="16.5" cy="11.5" r="1.3" fill="#ffd93b" stroke="none"/></svg>',card:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#8e5bd6" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M7 15v-4m0 0l2 2m-2-2l-2 2M13 11h4m-4 4h4" stroke-linecap="round"/></svg>',bye:'<svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#f0a52b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 4h5a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1h-5M10 17l5-5-5-5M15 12H3"/></svg>'};return m[k]}
function chipHTML(k,cls=''){const s=SIX.find(x=>x.k===k);return `<div class="chip ${cls}" data-chip="${k}"><div class="ic">${icSVG(s.icon)}</div><strong>${s.t}</strong></div>`}
function charImg(ck,h=250){const c=CHARS[ck];return `<img src="${A}${c.img}" style="height:${h}px;object-fit:contain;filter:drop-shadow(0 12px 20px rgba(23,50,77,.18))" alt="${c.name}">`}

